		void UpdateDistributionCentreTabPageCaption()
		{
			var distributionCentreDocAddress = Order.DistributionCentreDocAddress;

			if (distributionCentreDocAddress.E2_AddressOverride || distributionCentreDocAddress.Address == null ||
				distributionCentreDocAddress.Address.OA_Code.IsEmpty)
			{
				DistributionCentreTabPage.Text = ResString.GetMultilingualString("262ec8e5-5397-4b5f-a4ae-6763de7fb413", "Distribution Center");
			}
			else
			{
				var addressCaption = distributionCentreDocAddress.Address.OA_Code;
				if (addressCaption.Length > 6)
				{
					addressCaption = addressCaption.Substring(0, 6) + "...";
				}
				DistributionCentreTabPage.Text = ResString.GetMultilingualString("73c1c47f-d08c-4bcf-913e-3ca776bef726", "DC - {0}", addressCaption);
			}
		}

		void UpdateInventoryFiltersVisibility()
